def calculate_binary_search_trees(number):

    # Base case
    if number <= 1:
        return 1

    # Recursively call the function, summing the result
    total = 0
    for i in range(1, number + 1):
        total += calculate_binary_search_trees(i - 1) * calculate_binary_search_trees(number - i)
